/*
 * A387081  Indices k such that lpf(s(k-1)) does not divide abs(s(k) -
 *          s(k-1)), where s = A386482 and lpf = A020639.
 * https://oeis.org/A387081
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = n-th index k>=2 with lpf(s(k-1)) not dividing
 *            |s(k)-s(k-1)|, s = A386482 (generated by direct
 *            search/simulation)
 * Range:     u8 n <= 29, u16 n <= 2008, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Validated: standard, pass, 71 terms through n = 9662 (2026-11-10)
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

static uint64_t *A387081_s = NULL;
static size_t A387081_slen = 0, A387081_scap = 0;
static uint8_t *A387081_used = NULL;
static size_t A387081_ucap = 0;
static uint64_t *A387081_res = NULL;
static size_t A387081_rlen = 0, A387081_rcap = 0;

static void A387081_ensure_used(size_t need)
{
    if (need < A387081_ucap) return;
    size_t nc = A387081_ucap ? A387081_ucap : 1024;
    while (nc <= need) nc <<= 1;
    uint8_t *t = (uint8_t *)realloc(A387081_used, nc);
    if (!t) abort();
    memset(t + A387081_ucap, 0, nc - A387081_ucap);
    A387081_used = t;
    A387081_ucap = nc;
}

static void A387081_push_s(uint64_t v)
{
    if (A387081_slen == A387081_scap) {
        size_t nc = A387081_scap ? A387081_scap * 2 : 1024;
        uint64_t *t = (uint64_t *)realloc(A387081_s, nc * sizeof(uint64_t));
        if (!t) abort();
        A387081_s = t;
        A387081_scap = nc;
    }
    A387081_s[A387081_slen++] = v;
}

static void A387081_push_r(uint64_t v)
{
    if (A387081_rlen == A387081_rcap) {
        size_t nc = A387081_rcap ? A387081_rcap * 2 : 1024;
        uint64_t *t = (uint64_t *)realloc(A387081_res, nc * sizeof(uint64_t));
        if (!t) abort();
        A387081_res = t;
        A387081_rcap = nc;
    }
    A387081_res[A387081_rlen++] = v;
}

static uint64_t A387081_gcd(uint64_t a, uint64_t b)
{
    while (b) { uint64_t t = a % b; a = b; b = t; }
    return a;
}

static uint64_t A387081_lpf(uint64_t n)
{
    if (n <= 1) return 1;
    if ((n & 1) == 0) return 2;
    for (uint64_t i = 3; i <= n / i; i += 2)
        if (n % i == 0) return i;
    return n;
}

static void A387081_step(void)
{
    if (A387081_slen == 0) {
        A387081_ensure_used(4);
        A387081_push_s(1);
        A387081_push_s(2);
        A387081_used[1] = 1;
        A387081_used[2] = 1;
        return;
    }
    uint64_t prev = A387081_s[A387081_slen - 1];
    uint64_t cand = 0;
    bool found = false;
    uint64_t d;
    for (d = prev; d-- > 1; ) {
        if (!A387081_used[d] && A387081_gcd(prev, d) > 1) { cand = d; found = true; break; }
    }
    if (!found) {
        for (uint64_t u = prev + 1;; ++u) {
            A387081_ensure_used((size_t)u);
            if (!A387081_used[u] && A387081_gcd(prev, u) > 1) { cand = u; break; }
        }
    }
    A387081_ensure_used((size_t)cand);
    A387081_used[cand] = 1;
    A387081_push_s(cand);
    /* index k = slen (1-based), k >= 3 here; k=2 handled since lpf(1)=1 divides all */
    uint64_t p = A387081_lpf(prev);
    uint64_t diff = cand > prev ? cand - prev : prev - cand;
    if (diff % p != 0) A387081_push_r((uint64_t)A387081_slen);
}

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;
    if (A387081_slen == 0) A387081_step();
    while (A387081_rlen < (size_t)n)
        A387081_step();
    return (seq_t)A387081_res[(size_t)n - 1];
}
